<script setup>
import { presentationData } from '../../shared/presentation.js'
import { computed, inject, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { powerPlusSections } from '../navigation.js'
import { settingsStorage, settingsRevision } from '../settings-storage.js'
import { accountStorageKey } from '../account-storage.js'
import { powerPlusDefaults, percentCoverage, formatValue as fmt, annualEnergy, workOrderMetrics, tenantUsage, assetGraph, createDemoTenants } from '../powerplus.js'
import SystemReport from '../components/SystemReport.vue'
import { generatePowerPlusReport } from '../powerplus-reports.js'
import CardFavorite from '../components/CardFavorite.vue'
import TrendChart from '../components/TrendChart.vue'
import { widgets } from '../dashboard.js'
import AcControlPanel from '../components/AcControlPanel.vue'
import { inputTypes, inputValue, validateRange } from '../chart-range.js'
import { tenantRange } from '../tenant-range.js'
import TenantAnalytics from '../components/TenantAnalytics.vue'
import { acSimulation } from '../ac-simulation.js'
import { sustainabilityTotal } from '../../shared/sustainability.js'
import { powerPlusTelemetry, loadPowerPlusTelemetry } from '../powerplus-telemetry.js'
import { calculateSystemEfficiency, periodSystemEfficiency } from '../../shared/powerplus-demo.js'

const props = defineProps({ view: String, embedded: Boolean, heading: String, card: String })
const show = (...ids) => !props.card || ids.includes(props.card)
const route = useRoute(), api = inject('dataApi'), dark = inject('workspace-theme')
const data = ref(structuredClone(api.projectData))
const unsubscribe = api.subscribeData(next => { data.value = structuredClone(next) })
onBeforeUnmount(unsubscribe)
const section = computed(() => props.view || route.meta.section.replace('pp-', ''))
const page = computed(() => powerPlusSections.find(item => item.id === `pp-${section.value}`))
const telemetry = computed(() => powerPlusTelemetry.dataset)
const latestSample = computed(() => acSimulation.reading || telemetry.value?.readings.at(-1))
const efficiency = computed(() => calculateSystemEfficiency(latestSample.value))
const efficiencyPeriod = computed(() => periodSystemEfficiency(telemetry.value?.readings || []))
const environmentRows = computed(() => data.value.blocks.map(location => ({ ...location, ...(telemetry.value?.environments.find(row => row.locationId === location.id) || {}) })))
const demoReliability = computed(() => telemetry.value?.reliability)
const demoMtbf = computed(() => demoReliability.value?.failureCount > 0 ? demoReliability.value.operatingHours / demoReliability.value.failureCount : null)
const demoMttr = computed(() => demoReliability.value?.repairHours.length ? demoReliability.value.repairHours.reduce((sum, value) => sum + value, 0) / demoReliability.value.repairHours.length : null)
const reportOpen = ref(false)
function reportGenerator(data, options) { return generatePowerPlusReport(data, options, { state, dataset: telemetry.value, reading: latestSample.value, controls: acSimulation.settings, year: year.value, tenantId: selectedTenant.value || undefined }) }
const notice = ref(''), error = ref('')
const state = reactive(structuredClone(powerPlusDefaults))
for (const key of Object.keys(state)) {
  try {
    const stored = presentationData(JSON.parse(settingsStorage.getItem(accountStorageKey(`calypso.powerplus.${key}.v1`))))
    if (Array.isArray(state[key]) && Array.isArray(stored)) state[key] = stored
    else if (stored && typeof stored === 'object' && !Array.isArray(stored)) state[key] = { ...state[key], ...stored }
  } catch { /* Keep an empty workspace when saved data is malformed. */ }
}
for (const key of ['profile', 'air']) {
  const defaults = telemetry.value?.[key] || {}
  for (const [field, value] of Object.entries(defaults)) if (state[key][field] === null || state[key][field] === '') state[key][field] = value
}
watch(() => { settingsRevision.value; return Object.keys(state).map(key => settingsStorage.getItem(accountStorageKey(`calypso.powerplus.${key}.v1`))) }, (values, previous) => {
  values.forEach((value, index) => { if (value && value !== previous[index]) { try { state[Object.keys(state)[index]] = presentationData(JSON.parse(value)) } catch { /* Keep the last valid state. */ } } })
})
watch(section, () => { notice.value = ''; error.value = '' })
function save(key) {
  error.value = ''; notice.value = ''
  try { settingsStorage.setItem(accountStorageKey(`calypso.powerplus.${key}.v1`), JSON.stringify(state[key])); notice.value = 'Changes saved. Account sync status is shown above.'; return true }
  catch { error.value = 'Could not save. Keep this page open and retry.'; return false }
}
try {
  const seedKey = accountStorageKey('calypso.powerplus.tenant-samples.v1')
  if (settingsStorage.getItem(seedKey) !== 'true') {
    const samples = createDemoTenants(data.value, state.tenants)
    const availableArea = Number.isFinite(state.profile.nla) ? Math.max(0, state.profile.nla - state.tenants.reduce((sum, item) => sum + item.area, 0)) : null
    const sampleArea = samples.reduce((sum, item) => sum + item.area, 0)
    if (availableArea !== null && sampleArea > availableArea) samples.forEach(item => { item.area = Math.floor(item.area * availableArea / sampleArea * 100) / 100 })
    state.tenants.push(...samples.filter(item => item.area > 0))
    if (save('tenants')) settingsStorage.setItem(seedKey, 'true')
    notice.value = ''
  }
} catch { error.value = 'Could not save sample tenants. Reload to retry.' }
const id = prefix => `${prefix}-${crypto.randomUUID()}`
const date = value => value ? new Date(value).toLocaleString('en-SG', { timeZone: 'Asia/Singapore', dateStyle: 'medium', timeStyle: 'short' }) : 'Not recorded'
const now = () => new Date().toISOString()
const energyMeters = computed(() => data.value.sensors.filter(sensor => sensor.system === 'energy'))
const operational = computed(() => workOrderMetrics(state.workorders))
const total = field => data.value.blocks.map(block => block[field]).filter(Number.isFinite).reduce((a, b) => a + b, 0)
const energyBreakdown = computed(() => data.value.systems.filter(system => system.category === 'energy').map(system => {
  const meters = energyMeters.value.filter(meter => meter.systemId === system.id)
  const valid = meters.filter(meter => meter.online && !meter.faultCode && Number.isFinite(meter.today))
  return { ...system, value: valid.length ? valid.reduce((sum, meter) => sum + meter.today, 0) : null, coverage: `${valid.length}/${meters.length} valid meters` }
}))
const chart = name => widgets.find(widget => widget.id === name)
const orderForm = reactive({ title: '', assetId: '', assignee: '', kind: 'Maintenance', failureAt: '' })
function addOrder() {
  error.value = ''
  if (!orderForm.title.trim() || !orderForm.assetId || !orderForm.assignee.trim()) { error.value = 'Enter a task, equipment and assignee.'; return }
  if (orderForm.kind === 'Failure' && (!orderForm.failureAt || Date.parse(orderForm.failureAt) > Date.now())) { error.value = 'Enter the failure start time, no later than now.'; return }
  state.workorders.push({ ...orderForm, title: orderForm.title.trim(), id: id('WO'), createdAt: now(), failureAt: orderForm.kind === 'Failure' ? new Date(orderForm.failureAt).toISOString() : null, status: 'Pending', history: [{ status: 'Pending', at: now() }] })
  if (save('workorders')) { orderForm.title = ''; orderForm.failureAt = '' }
}
function orderStatus(order, value) { order.status = value; order.completedAt = value === 'Completed' ? now() : null; order.history.push({ status: value, at: now() }); save('workorders') }
const year = ref('2025')
const annual = computed(() => annualEnergy(data.value, year.value))
const eui = computed(() => Number.isFinite(state.profile.gfa) && state.profile.gfa > 0 && Number.isFinite(annual.value) ? annual.value / state.profile.gfa : null)
function saveProfile() {
  if (!state.profile.site.trim() || !Number.isFinite(state.profile.gfa) || state.profile.gfa <= 0 || !Number.isFinite(state.profile.nla) || state.profile.nla <= 0 || state.profile.nla > state.profile.gfa) { error.value = 'Enter a site name and positive areas, with NLA no greater than gross floor area.'; return }
  if (state.tenants.reduce((sum, tenant) => sum + tenant.area, 0) > state.profile.nla) { error.value = 'Total NLA cannot be smaller than the registered tenant area.'; return }
  save('profile')
}
function savedTenant() { try { const value = JSON.parse(settingsStorage.getItem(accountStorageKey('calypso.powerplus.tenant-selection.v1')) || '""'); return typeof value === 'string' ? value : '' } catch { return '' } }
const selectedTenant = ref(savedTenant())
watch(() => { settingsRevision.value; return savedTenant() }, value => { selectedTenant.value = value })
watch(selectedTenant, value => settingsStorage.setItem(accountStorageKey('calypso.powerplus.tenant-selection.v1'), JSON.stringify(value)))
const tenantCoverage = computed(() => percentCoverage(state.tenants.reduce((sum, tenant) => sum + tenant.area, 0), state.profile.nla))
const tenant = computed(() => state.tenants.find(item => item.id === selectedTenant.value) || (state.tenants.length ? { id: 'overall', name: 'Overall', area: state.tenants.reduce((sum, item) => sum + item.area, 0), meterIds: [...new Set(state.tenants.flatMap(item => item.meterIds))] } : null))
const tenantMeters = computed(() => tenant.value ? data.value.sensors.filter(meter => tenant.value.meterIds.includes(meter.id)) : [])
const tenantPeriod = ref('daily'), tenantFrom = ref(''), tenantTo = ref(''), appliedFrom = ref(''), appliedTo = ref(''), tenantRangeError = ref('')
function resetTenantRange() {
  const rows = tenant.value ? tenantUsage(tenant.value, data.value, tenantPeriod.value).rows : []
  const labels = rows.length ? rows.map(row => row.label) : data.value.trends.periods[tenantPeriod.value].labels
  tenantFrom.value = inputValue(tenantPeriod.value, labels[0]); tenantTo.value = inputValue(tenantPeriod.value, labels.at(-1))
  applyTenantRange()
}
function applyTenantRange() {
  tenantRangeError.value = validateRange(tenantPeriod.value, tenantFrom.value, tenantTo.value)
  if (!tenantRangeError.value) { appliedFrom.value = tenantFrom.value; appliedTo.value = tenantTo.value }
}
watch([tenantPeriod, () => tenant.value?.id], resetTenantRange, { immediate: true })
const usage = computed(() => tenant.value ? tenantRange(tenant.value, data.value, tenantPeriod.value, appliedFrom.value, appliedTo.value) : { today: null, rows: [] })
const airCoverage = computed(() => percentCoverage(state.air.coveredArea, state.air.landlordArea))
function saveAir() {
  if (airCoverage.value === null) { error.value = 'Enter positive landlord-controlled area and a covered area between zero and that total.'; return }
  save('air')
}
const pointSearch = ref('')
const points = computed(() => data.value.sensors.filter(point => `${point.id} ${point.name} ${point.systemName}`.toLowerCase().includes(pointSearch.value.toLowerCase())))
const naming = point => [state.profile.site, state.profile.building || 'Building', point.locationId, point.systemId, point.id, point.system === 'energy' ? 'EnergyConsumption' : 'WaterConsumption'].map(part => part.replace(/[^A-Za-z0-9_]/g, '_')).join('-')
const handover = ['Network schematic', 'Controller and point connection diagrams', 'BMS point list and naming convention', 'Control logic and configuration files', 'HMI user guide', 'Change-control and rollback procedure', 'Training records']
const documentForm = reactive({ title: handover[0], url: '' })
function addDocument() {
  try { if (!['http:', 'https:'].includes(new URL(documentForm.url).protocol)) throw new Error() }
  catch { error.value = 'Enter an HTTP or HTTPS document link.'; return }
  state.integration.documents.push({ ...documentForm, id: id('DOC') })
  if (save('integration')) documentForm.url = ''
}
function download(name, content, type = 'application/json') {
  const blob = new Blob([typeof content === 'string' ? content : JSON.stringify(content, null, 2)], { type })
  const url = URL.createObjectURL(blob), link = document.createElement('a')
  link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
}
</script>

<template>
  <component :is="embedded ? 'section' : 'main'" class="pp-page" :class="{ 'pp-embedded': embedded }">
    <div v-if="!card" class="page-heading"><div><p v-if="!embedded" class="eyebrow">POWERPLUS / {{ state.profile.site }}</p><component :is="embedded ? 'h2' : 'h1'">{{ heading || page.label }}</component><p class="subtitle">{{ page.requirement }} · Sustainability and building operations</p></div><RouterLink v-if="!embedded && section !== 'operational'" to="/dashboard" class="pp-back">My dashboard <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></RouterLink></div>
    <div v-if="!card" class="pp-report-actions"><button class="primary" @click="reportOpen = true"><i aria-hidden="true" class="fa-solid fa-file-lines"></i> Generate {{ embedded ? (section === 'air' ? 'AC' : 'BMS assets') + ' report' : 'report' }}</button></div>
    <slot name="navigation" />
    <div v-if="!embedded" class="pp-context"><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>Building readings are illustrative samples. Site connections and verification evidence are required before these views can demonstrate the PDF requirements.</span></div>
    <div v-if="powerPlusTelemetry.error" class="pp-error" role="alert">{{ powerPlusTelemetry.error }} <button @click="loadPowerPlusTelemetry">Retry sample data</button></div>
    <p v-if="error" class="pp-error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>

    <template v-if="section === 'operational'">
      <div class="pp-metrics"><article v-if="show('energy')"><CardFavorite v-if="!card" id="energy"/><span>Today's electricity</span><strong>{{ fmt(total('energyKwh')) }} <small>kWh</small></strong><p>Configured sample locations</p></article><article v-if="show('tse')"><CardFavorite v-if="!card" id="tse"/><span>Total system efficiency</span><strong data-testid="tse-value">{{ fmt(efficiency.efficiency) }} <small>kW/RT</small></strong><p>{{ fmt(efficiency.powerKw) }} kW / {{ fmt(efficiency.coolingLoadRt) }} RT - synchronized readings</p></article><article v-if="show('pp-active-workorders')"><CardFavorite v-if="!card" id="pp-active-workorders"/><span>Active work orders</span><strong>{{ operational.active }}</strong><p>Pending and in progress</p></article><article v-if="show('pp-energy-meters')"><CardFavorite v-if="!card" id="pp-energy-meters"/><span>Connected energy meters</span><strong>{{ energyMeters.filter(m => m.online && !m.faultCode).length }} / {{ energyMeters.length }}</strong><p>Faulty readings excluded from breakdown</p></article></div>
<section v-if="!card" class="pp-panel"><h2>Operational data</h2><p>Daily totals for the configured building locations. Waste is available where collection readings exist; rooftop solar is assigned to Level 4.</p><div class="pp-metrics"><article v-for="metric in [{id:'energy',field:'electricityKwh',title:'Total electricity consumption',unit:'kWh'},{id:'water',field:'waterM3',title:'Total water consumption',unit:'m\u00b3'},{id:'waste',field:'wasteKg',title:'Waste generation',unit:'kg'},{id:'renewable',field:'renewableKwh',title:'On-site renewable energy generation',unit:'kWh'}]" :key="metric.field" v-show="show(metric.id)"><CardFavorite v-if="!card" :id="metric.id"/><span>{{ metric.title }}</span><strong>{{ fmt(sustainabilityTotal(telemetry, metric.field)) }} <small>{{ metric.unit }}</small></strong></article></div><h2>Energy performance data</h2><div class="pp-metrics"><article v-for="metric in [{id:'acmv-energy',field:'acmvKwh',title:'Air-conditioning and mechanical ventilation (ACMV)'},{id:'lighting-energy',field:'lightingKwh',title:'Lighting'},{id:'lifts-energy',field:'liftsKwh',title:'Lifts and escalators'}]" :key="metric.field" v-show="show(metric.id)"><CardFavorite v-if="!card" :id="metric.id"/><span>{{ metric.title }}</span><strong>{{ fmt(sustainabilityTotal(telemetry, metric.field)) }} <small>kWh</small></strong></article></div><p>ACMV, lighting and vertical transport sum to total electricity consumption for this simulated reporting day. Solar generation is reported separately from consumption.</p></section>
      <div class="pp-columns"><section v-if="show('pp-energy-breakdown')" class="pp-panel"><CardFavorite v-if="!card" id="pp-energy-breakdown"/><h2>Energy consumption breakdown</h2><p>Available ACMV sample meters. Lighting and lifts/escalators are not metered in this dataset.</p><div class="pp-breakdown" v-for="system in energyBreakdown" :key="system.id"><div><strong>{{ system.name }}</strong><small>{{ system.coverage }}</small></div><span>{{ fmt(system.value) }} kWh</span></div></section><section v-if="show('energy-trend')" class="pp-panel pp-chart"><CardFavorite v-if="!card" id="energy-trend"/><h2>Electricity profile</h2><TrendChart :widget="chart('energy-trend')" :blocks="data.blocks.filter(b => Number.isFinite(b.energyKwh))" :trends="data.trends" :dark="dark" /></section></div>
      <section v-if="latestSample && show('pp-acmv-details', 'pp-weighted-efficiency')" class="pp-panel acmv-efficiency"><CardFavorite v-if="!card" id="pp-acmv-details"/><div class="pp-row"><div><h2>ACMV system efficiency</h2><p>{{ powerPlusTelemetry.source }} - Simulated sample at {{ date(latestSample.timestamp) }} SGT</p></div><span class="tag">Simulated data</span></div><p>Total system efficiency = total ACMV electrical power (kW) / cooling load (RT). The water-side and air-side readings share the same timestamp.</p><div class="pp-metrics"><article v-if="show('pp-ac-power')"><CardFavorite v-if="!card" id="pp-ac-power"/><span>ACMV electrical power</span><strong>{{ fmt(efficiency.powerKw) }} <small>kW</small></strong></article><article v-if="show('pp-ac-cooling')"><CardFavorite v-if="!card" id="pp-ac-cooling"/><span>Cooling load</span><strong>{{ fmt(efficiency.coolingLoadRt) }} <small>RT</small></strong></article><article v-if="show('pp-weighted-efficiency')"><CardFavorite v-if="!card" id="pp-weighted-efficiency"/><span>24-hour weighted efficiency</span><strong>{{ fmt(efficiencyPeriod.efficiency) }} <small>kW/RT</small></strong><p>{{ fmt(efficiencyPeriod.energyKwh) }} kWh / {{ fmt(efficiencyPeriod.coolingRth) }} RTh</p></article></div><div class="pp-columns"><div class="table-scroll"><table><thead><tr><th>Power component</th><th>Electrical power (kW)</th></tr></thead><tbody><tr v-for="component in latestSample.components" :key="component.id"><td>{{ component.name }}</td><td>{{ fmt(component.powerKw) }}</td></tr><tr><td><strong>Total</strong></td><td><strong>{{ fmt(efficiency.powerKw) }}</strong></td></tr></tbody></table></div><div><h3>Cooling measurement inputs</h3><p>Chilled-water supply: <strong>{{ fmt(latestSample.chilledWaterSupplyC) }} &deg;C</strong><br />Chilled-water return: <strong>{{ fmt(latestSample.chilledWaterReturnC) }} &deg;C</strong><br />Water flow: <strong>{{ fmt(latestSample.chilledWaterFlowLs) }} L/s</strong><br />Cooling load: <strong>{{ fmt(latestSample.coolingLoadRt) }} RT</strong></p><p>All five power components and cooling load are required for a valid TSE. This sample is illustrative and is not a verified site performance result.</p></div></div><details><summary>View all 24 synchronized samples</summary><div class="table-scroll pp-history"><table><thead><tr><th>Sample time (SGT)</th><th>ACMV power (kW)</th><th>Cooling load (RT)</th><th>TSE (kW/RT)</th></tr></thead><tbody><tr v-for="reading in telemetry.readings" :key="reading.timestamp"><td>{{ date(reading.timestamp) }}</td><td>{{ fmt(calculateSystemEfficiency(reading).powerKw) }}</td><td>{{ fmt(reading.coolingLoadRt) }}</td><td>{{ fmt(calculateSystemEfficiency(reading).efficiency) }}</td></tr></tbody></table></div></details><button @click="download('powerplus-acmv-data.json', telemetry)">Download ACMV dataset</button></section>
      <section v-if="show('pp-workorders')" class="pp-panel"><CardFavorite v-if="!card" id="pp-workorders"/><h2>Work orders</h2><p>Create and track maintenance tasks and equipment failures.</p><form class="pp-form" @submit.prevent="addOrder"><label>Task<input v-model="orderForm.title" maxlength="160" required /></label><label>Equipment<select aria-label="Equipment" v-model="orderForm.assetId" required><option disabled value="">Select equipment</option><option v-for="asset in data.assets" :value="asset.id" :key="asset.id">{{ asset.name }}</option></select></label><label>Assigned to<input v-model="orderForm.assignee" maxlength="100" required /></label><label>Type<select aria-label="Type" v-model="orderForm.kind"><option>Maintenance</option><option>Failure</option></select></label><label v-if="orderForm.kind === 'Failure'">Failure started<input v-model="orderForm.failureAt" type="datetime-local" required /></label><button class="primary">Create work order</button></form><div class="table-scroll"><table><thead><tr><th>Reference / task</th><th>Equipment</th><th>Assignee</th><th>Status</th></tr></thead><tbody><tr v-for="order in state.workorders" :key="order.id"><td><strong>{{ order.title }}</strong><small class="pp-id">{{ order.id }}</small></td><td>{{ data.assets.find(a => a.id === order.assetId)?.name }}</td><td>{{ order.assignee }}</td><td><label class="pp-inline">Update {{ order.title }}<select :value="order.status" :aria-label="`Status for ${order.title}`" @change="orderStatus(order, $event.target.value)"><option>Pending</option><option>In progress</option><option>Completed</option></select></label><details><summary>History</summary><p v-for="(entry, index) in order.history" :key="index">{{ entry.status }} · {{ date(entry.at) }}</p></details></td></tr><tr v-if="!state.workorders.length"><td colspan="4">No work orders yet.</td></tr></tbody></table></div></section>
    </template>

    <template v-else-if="section === 'managerial'">
      <div v-if="!card" class="pp-controls"><label>Reporting year<select aria-label="Reporting year" v-model="year"><option v-for="value in data.trends.periods.yearly.labels" :key="value">{{ value }}</option></select></label><span>{{ year === '2026' ? '2026 is year to date, through 12 October; EUI is partial.' : 'Complete sample year' }}</span></div>
      <div class="pp-metrics"><article v-if="show('pp-eui')"><CardFavorite v-if="!card" id="pp-eui"/><span>Energy use intensity</span><strong>{{ fmt(eui) }} <small>kWh/m²{{ year === '2026' ? ' YTD' : '/year' }}</small></strong><p>{{ eui === null ? 'Configure gross floor area below' : 'Sample electricity / configured GFA' }}</p></article><article v-if="show('pp-mtbf')"><CardFavorite v-if="!card" id="pp-mtbf"/><span>Mean time between failures</span><strong>{{ fmt(demoMtbf) }} <small>hours</small></strong><p>Sample reliability sample - {{ fmt(demoReliability?.operatingHours) }} operating hours / {{ demoReliability?.failureCount }} failures</p></article><article v-if="show('pp-mttr')"><CardFavorite v-if="!card" id="pp-mttr"/><span>Mean time to repair</span><strong>{{ fmt(operational.mttr ?? demoMttr) }} <small>hours</small></strong><p>{{ operational.repairedFailures ? operational.repairedFailures + ' resolved failure records' : 'Sample reliability sample - 2 repairs (3 h and 5 h)' }}</p></article><article v-if="show('pp-annual')"><CardFavorite v-if="!card" id="pp-annual"/><span>Annual electricity</span><strong>{{ fmt(annual) }} <small>kWh</small></strong><p>Configured locations; sample history</p></article></div>
      <div class="pp-columns"><section v-if="show('energy-trend')" class="pp-panel pp-chart"><CardFavorite v-if="!card" id="energy-trend"/><h2>Electricity benchmarking</h2><p>Compare historical periods using the chart controls.</p><TrendChart :widget="chart('energy-trend')" :blocks="data.blocks.filter(b => Number.isFinite(b.energyKwh))" :trends="data.trends" :dark="dark" /></section><section v-if="show('water-trend')" class="pp-panel pp-chart"><CardFavorite v-if="!card" id="water-trend"/><h2>Water benchmarking</h2><TrendChart :widget="chart('water-trend')" :blocks="data.blocks.filter(b => Number.isFinite(b.waterM3))" :trends="data.trends" :dark="dark" /></section></div>
      <section v-if="show('pp-building-profile')" class="pp-panel"><CardFavorite v-if="!card" id="pp-building-profile"/><h2>Building profile</h2><p>Sample areas are supplied with the backend dataset. Replace them with verified site areas for operational reporting.</p><form class="pp-form" @submit.prevent="saveProfile"><label>Site name<input v-model="state.profile.site" maxlength="100" required /></label><label>Building name<input v-model="state.profile.building" maxlength="100" /></label><label>Gross floor area (m²)<input v-model.number="state.profile.gfa" type="number" min="0.01" step="0.01" required /></label><label>Total net lettable area (m²)<input v-model.number="state.profile.nla" type="number" min="0.01" step="0.01" required /></label><button class="primary">Save building profile</button></form></section>
    </template>

    <template v-else-if="section === 'air'">
      <AcControlPanel :card="card" />
      <div class="pp-metrics"><article v-if="show('pp-ac-mode')"><CardFavorite v-if="!card" id="pp-ac-mode"/><span>Adaptive control connection</span><strong>Sample simulation</strong><p>Environmental sample data ? no live control</p></article><article v-if="show('pp-ac-coverage')"><CardFavorite v-if="!card" id="pp-ac-coverage"/><span>Landlord air-side coverage</span><strong>{{ fmt(airCoverage) }} <small>%</small></strong><p>PDF coverage requirement: at least 85%</p></article><article v-if="show('pp-ac-target')"><CardFavorite v-if="!card" id="pp-ac-target"/><span>Outcome-based target</span><strong>{{ state.air.target || 'Not defined' }}</strong><p>Requires a contract and M&amp;V evidence</p></article></div>
      <section v-if="show('pp-ac-environment')" class="pp-panel"><CardFavorite v-if="!card" id="pp-ac-environment"/><h2>Environmental inputs</h2><p>Simulated readings as of {{ date(telemetry?.sampleEnd) }} SGT.</p><div class="table-scroll"><table><thead><tr><th>Location</th><th>Temperature (&deg;C)</th><th>Occupancy</th><th>CO<sub>2</sub> (ppm)</th><th>Humidity (%)</th><th>Outdoor (&deg;C)</th><th>AHU fan (%)</th></tr></thead><tbody><tr v-for="location in environmentRows" :key="location.id"><td>{{ location.name }}</td><td>{{ fmt(location.temperatureC) }}</td><td>{{ fmt(location.occupancy) }}</td><td>{{ fmt(location.co2Ppm) }}</td><td>{{ fmt(location.relativeHumidityPercent) }}</td><td>{{ fmt(location.outdoorTemperatureC) }}</td><td>{{ fmt(location.ahuFanPercent) }}</td></tr></tbody></table></div><p>Sample setpoints: supply air 14 &deg;C, zone temperature 24 &deg;C and static pressure 250 Pa. These are simulated monitoring values; no equipment commands are sent.</p></section>
      <section v-if="show('pp-ac-plan')" class="pp-panel"><CardFavorite v-if="!card" id="pp-ac-plan"/><h2>Adaptive AC performance plan</h2><form class="pp-form" @submit.prevent="saveAir"><label>Landlord-controlled AC floor area (m²)<input v-model.number="state.air.landlordArea" type="number" min="0.01" step="0.01" required /></label><label>Adaptively controlled floor area (m²)<input v-model.number="state.air.coveredArea" type="number" min="0" step="0.01" required /></label><label>Energy performance target<input v-model="state.air.target" placeholder="Define a measurable target" maxlength="200" /></label><label>Contract reference<input v-model="state.air.contract" maxlength="200" /></label><label class="pp-full">Measurement and verification methodology<textarea v-model="state.air.methodology" maxlength="3000" rows="3"></textarea></label><button class="primary">Save AC plan</button></form><p>Fixed schedules or static setpoints alone do not demonstrate adaptive optimization. Coverage and saved plans are declarations, pending technical verification.</p></section>
    </template>

    <template v-else-if="section === 'tenants'">
      <div class="pp-metrics"><article v-if="show('pp-tenant-count')"><CardFavorite v-if="!card" id="pp-tenant-count"/><span>Registered tenants</span><strong>{{ state.tenants.length }}</strong><p>Admin-managed meter assignments</p></article><article v-if="show('pp-tenant-coverage')"><CardFavorite v-if="!card" id="pp-tenant-coverage"/><span>Participating tenant area</span><strong>{{ fmt(tenantCoverage) }} <small>% NLA</small></strong><p>PDF coverage requirement: at least 50%</p></article><article v-if="show('pp-tenant-access')"><CardFavorite v-if="!card" id="pp-tenant-access"/><span>Tenant access</span><strong>Admin preview</strong><p>Individual tenant sign-in is not connected</p></article></div>
      <section class="pp-panel"><h2 v-if="!card">Tenant energy view</h2><TenantAnalytics v-if="tenant" :tenant="tenant" :data="data" :period="tenantPeriod" :from="appliedFrom" :to="appliedTo" :card="card"><template #filters><div v-if="!card || ['pp-tenant-live','pp-tenant-history','pp-tenant-baseline','pp-tenant-meters','pp-tenant-readings'].includes(card)" class="tenant-filter-panel"><div class="tenant-filter-title"><div><h3>Tenant &amp; reporting period</h3><p>Choose a tenant and a date range for consumption history and performance comparisons.</p></div><span v-if="tenant" class="tag">{{ tenant.name }} &middot; {{ fmt(tenant.area) }} m&sup2;</span></div><div class="tenant-filter-fields"><label>Tenant<select aria-label="Tenant" v-model="selectedTenant"><option value="">Overall</option><option v-for="item in state.tenants" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>History interval<select aria-label="History interval" v-model="tenantPeriod"><option value="hourly">Hourly</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select></label><label>From<input v-model="tenantFrom" :type="inputTypes[tenantPeriod]" :step="tenantPeriod === 'hourly' ? 3600 : tenantPeriod === 'yearly' ? 1 : undefined" aria-label="Tenant history From" /></label><label>To<input v-model="tenantTo" :type="inputTypes[tenantPeriod]" :step="tenantPeriod === 'hourly' ? 3600 : tenantPeriod === 'yearly' ? 1 : undefined" aria-label="Tenant history To" /></label><div class="tenant-filter-actions"><button class="primary" @click="applyTenantRange">Apply range</button><button @click="resetTenantRange">Reset range</button></div></div><p v-if="tenantRangeError" class="pp-error" role="alert">{{ tenantRangeError }}</p><p v-else class="tenant-range-summary" role="status">{{ usage.rows.length }} {{ tenantPeriod }} intervals &middot; {{ appliedFrom }} to {{ appliedTo }} &middot; Inclusive calendar periods (UTC)</p></div></template></TenantAnalytics><template v-if="tenant"><div v-if="show('pp-tenant-meters')" class="tenant-source"><CardFavorite v-if="!card" id="pp-tenant-meters"/><h3>Assigned tenant energy sensors</h3><div class="table-scroll tenant-table-scroll"><table><thead><tr><th>Assigned energy sensor</th><th>Location</th><th>Current demand (kW)</th><th>Today (kWh)</th></tr></thead><tbody><tr v-for="meter in tenantMeters" :key="meter.id"><td>{{ meter.name }}<small class="pp-id">{{ meter.id }}</small></td><td>{{ data.locations.find(location => location.id === meter.blockId)?.name }}</td><td>{{ fmt(meter.rate) }}</td><td>{{ fmt(meter.online && !meter.faultCode ? meter.today : null) }}</td></tr></tbody></table></div></div><div v-if="show('pp-tenant-readings')" class="tenant-source"><CardFavorite v-if="!card" id="pp-tenant-readings"/><h3>Tenant consumption readings</h3><div class="table-scroll pp-history tenant-table-scroll"><table><thead><tr><th>Period</th><th>Electricity (kWh)</th><th>Change from previous period</th></tr></thead><tbody><tr v-for="(row, index) in usage.rows" :key="row.label"><td>{{ row.label }}</td><td>{{ fmt(row.value) }}</td><td>{{ fmt(index && Number.isFinite(row.value) && usage.rows[index - 1].value > 0 ? (row.value / usage.rows[index - 1].value - 1) * 100 : null) }} %</td></tr><tr v-if="!usage.rows.length"><td colspan="3">No valid readings for the assigned meters.</td></tr></tbody></table></div></div><button v-if="!card || card === 'pp-tenant-readings'" @click="download('tenant-energy.json', { tenant: tenant.name, dataMode: 'Allocated sample history', period: tenantPeriod, from: appliedFrom, to: appliedTo, rows: usage.rows })">Download tenant report</button><p v-if="!card">Compare like-for-like periods and investigate sustained increases. Peer benchmarks and automated anomaly thresholds need a verified tenant baseline.</p></template><p v-else>No tenants configured. Add a tenant and assign its energy meters below.</p></section>
    </template>

    <template v-else-if="section === 'open'">
      <div class="pp-columns"><section v-if="show('pp-integration')" class="pp-panel"><CardFavorite v-if="!card" id="pp-integration"/><h2>Open BMS connection</h2><p>Record the intended gateway and documentation. Saving a protocol does not establish a physical connection.</p><form class="pp-form pp-single" @submit.prevent="save('integration')"><label>Standard protocol<select aria-label="Standard protocol" v-model="state.integration.protocol"><option>BACnet</option><option>Modbus</option><option>MQTT</option><option>OPC UA</option><option>REST API</option></select></label><label>Gateway / controller reference<input v-model="state.integration.gateway" maxlength="200" /></label><label>API documentation URL<input v-model="state.integration.apiDocumentation" type="url" maxlength="500" /></label><label>Target asset ontology<select aria-label="Target asset ontology" v-model="state.integration.ontology"><option>Brick Schema</option><option>Project Haystack</option><option>RealEstateCore</option></select></label><button class="primary">Save integration details</button></form></section><section v-if="show('pp-asset-graph')" class="pp-panel"><CardFavorite v-if="!card" id="pp-asset-graph"/><h2>Asset relationships</h2><p>Site → building → locations → systems → equipment → data points.</p><div class="pp-chips"><span>{{ data.locations.length }} locations</span><span>{{ data.systems.length }} systems</span><span>{{ data.assets.length }} equipment items</span><span>{{ data.sensors.length }} points</span></div><p>The downloadable graph contains existing relationships. Its mapping to {{ state.integration.ontology }} remains to be implemented and validated.</p><button @click="download('powerplus-asset-relationships.json', assetGraph(data, state.profile))">Download asset relationships</button><h3>Read-only account API</h3><p><code>GET /api/powerplus?resource=assets</code><br /><code>GET /api/powerplus?resource=points</code></p><p>Returns configured sample data and relationships. Requires a PowerPlus server session. No equipment control API is connected.</p></section></div>
      <section v-if="show('pp-point-list')" class="pp-panel"><CardFavorite v-if="!card" id="pp-point-list"/><h2>Point list and naming convention</h2><p>Proposed names follow Site–Building–Level–System–Equipment–Point Type. Protocol addresses, register numbers and controller links await the contractor point schedule.</p><label>Find a data point<input v-model="pointSearch" type="search" placeholder="Search name, system or point ID" /></label><div class="table-scroll pp-history"><table><thead><tr><th>Point</th><th>Proposed machine-readable name</th><th>Location / system</th><th>Controller / register</th></tr></thead><tbody><tr v-for="point in points" :key="point.id"><td>{{ point.name }}<small class="pp-id">{{ point.id }}</small></td><td><code>{{ naming(point) }}</code></td><td>{{ point.locationId }} / {{ point.systemName }}</td><td>Not supplied</td></tr></tbody></table></div><button @click="download('powerplus-point-list.json', points.map(p => ({ id: p.id, proposedName: naming(p), locationId: p.locationId, systemId: p.systemId, controller: null, register: null })))">Download point list</button></section>
      <section v-if="show('pp-handover')" class="pp-panel"><CardFavorite v-if="!card" id="pp-handover"/><h2>Training and handover register</h2><p>Record owner-accessible documents and training evidence. Control logic ownership and third-party access require contractual confirmation.</p><form class="pp-form" @submit.prevent="addDocument"><label>Document type<select aria-label="Document type" v-model="documentForm.title"><option v-for="item in handover" :key="item">{{ item }}</option></select></label><label>Document link<input v-model="documentForm.url" type="url" required maxlength="500" /></label><button class="primary">Add handover document</button></form><div class="pp-breakdown" v-for="item in handover" :key="item"><span>{{ item }}</span><span>{{ state.integration.documents.some(doc => doc.title === item) ? 'Link recorded; verify evidence' : 'Awaiting evidence' }}</span></div><ul class="pp-document-list"><li v-for="doc in state.integration.documents" :key="doc.id"><a :href="doc.url" target="_blank" rel="noopener noreferrer">{{ doc.title }}</a><button @click="state.integration.documents = state.integration.documents.filter(d => d.id !== doc.id); save('integration')">Remove document</button></li></ul></section>
    </template>

    <Teleport to="body"><SystemReport v-if="reportOpen" :system="section" :data="data" block-id="all" :generator="reportGenerator" @close="reportOpen = false"/></Teleport>
  </component>
</template>

